PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS challenges (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, phase TEXT NOT NULL DEFAULT 'waiting', duration INTEGER NOT NULL DEFAULT 300, ends_at INTEGER, remaining INTEGER NOT NULL DEFAULT 300, published INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS players (id TEXT PRIMARY KEY, challenge_id TEXT NOT NULL REFERENCES challenges(id) ON DELETE CASCADE, name TEXT NOT NULL, token TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS drawings (id TEXT PRIMARY KEY, player_id TEXT NOT NULL REFERENCES players(id) ON DELETE CASCADE, item_id TEXT NOT NULL, item_name TEXT NOT NULL, icon TEXT NOT NULL, image_key TEXT NOT NULL, reviewed INTEGER NOT NULL DEFAULT 0, correct INTEGER, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS scores (challenge_id TEXT NOT NULL REFERENCES challenges(id) ON DELETE CASCADE, player_id TEXT NOT NULL REFERENCES players(id) ON DELETE CASCADE, mobkills INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(challenge_id,player_id));